import heapq

def match(orders):
    trades = []
    buy_book = []  # heap of (-price, arrival, id)
    sell_book = []  # heap of (price, arrival, id)
    order_info = {}  # id -> dict with side, price, qty, arrival, active
    arrival_counter = 0

    def clean_buy():
        while buy_book:
            negp, arr, oid = buy_book[0]
            info = order_info.get(oid)
            if info is None or not info['active'] or info['qty'] <= 0:
                heapq.heappop(buy_book)
            else:
                break

    def clean_sell():
        while sell_book:
            p, arr, oid = sell_book[0]
            info = order_info.get(oid)
            if info is None or not info['active'] or info['qty'] <= 0:
                heapq.heappop(sell_book)
            else:
                break

    for order in orders:
        typ = order[0]
        if typ == 'cancel':
            oid = order[1]
            info = order_info.get(oid)
            if info is not None and info['active'] and info['qty'] > 0:
                info['active'] = False
            continue

        arrival_counter += 1
        arrival = arrival_counter

        if typ == 'limit':
            _, oid, side, price, qty = order
        elif typ == 'ioc':
            _, oid, side, price, qty = order
        elif typ == 'market':
            _, oid, side, qty = order
            price = None
        else:
            continue

        remaining = qty
        order_info[oid] = {'side': side, 'price': price, 'qty': remaining, 'arrival': arrival, 'active': True}

        if side == 'buy':
            # match against sell_book
            while remaining > 0:
                clean_sell()
                if not sell_book:
                    break
                sp, sarr, sid = sell_book[0]
                if typ != 'market' and sp > price:
                    break
                sinfo = order_info[sid]
                trade_qty = min(remaining, sinfo['qty'])
                trades.append([oid, sid, sp, trade_qty])
                remaining -= trade_qty
                sinfo['qty'] -= trade_qty
                order_info[oid]['qty'] = remaining
                if sinfo['qty'] <= 0:
                    sinfo['active'] = False
                    heapq.heappop(sell_book)
            order_info[oid]['qty'] = remaining
            if typ == 'limit' and remaining > 0:
                heapq.heappush(buy_book, (-price, arrival, oid))
            else:
                if remaining <= 0 or typ != 'limit':
                    order_info[oid]['active'] = False

        else:  # sell
            while remaining > 0:
                clean_buy()
                if not buy_book:
                    break
                negp, barr, bid = buy_book[0]
                bp = -negp
                if typ != 'market' and bp < price:
                    break
                binfo = order_info[bid]
                trade_qty = min(remaining, binfo['qty'])
                trades.append([bid, oid, bp, trade_qty])
                remaining -= trade_qty
                binfo['qty'] -= trade_qty
                order_info[oid]['qty'] = remaining
                if binfo['qty'] <= 0:
                    binfo['active'] = False
                    heapq.heappop(buy_book)
            order_info[oid]['qty'] = remaining
            if typ == 'limit' and remaining > 0:
                heapq.heappush(sell_book, (price, arrival, oid))
            else:
                if remaining <= 0 or typ != 'limit':
                    order_info[oid]['active'] = False

    return trades

